#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

# ── Project constants ─────────────────────────────────────────────────────
GH_OWNER="ahparikh"
GH_REPO="watchmakers-bench"
SSH_HOST="github-personal"                      # SSH alias from ~/.ssh/config, same as websites/shahparikh
SSH_URL="git@${SSH_HOST}:${GH_OWNER}/${GH_REPO}.git"
SUBMODULE_PATH="websites/anthropic"
PREVIEW_BRANCH="hosting-preview-check"
PREVIEW_PATH_PATTERN='https://<branch>.<project>.pages.dev'

# Run from the project root regardless of where the script was invoked.
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
PARENT="$(cd "$ROOT/../.." && pwd)"              # ~/.personal/code, the repo that holds the submodules

# State lives in a tiny dotenv file (git-ignored) so every stage can be re-run.
ENV_FILE="$ROOT/docs/.hosting.env"

# _http_ok URL: 200-299 within 20s.
_http_ok() {
  local code
  code=$(curl -sS -o /dev/null -L --max-time 20 -w '%{http_code}' "$1" 2>/dev/null || echo 000)
  [[ "$code" =~ ^2 ]]
}

# _wait_http URL SECONDS: poll until _http_ok or timeout. Prints a dot per try.
_wait_http() {
  local url="$1" deadline=$(( $(date +%s) + ${2:-180} ))
  while (( $(date +%s) < deadline )); do
    if _http_ok "$url"; then printf '\n'; return 0; fi
    printf '.'; sleep 10
  done
  printf '\n'; return 1
}

banner "Watchmaker's Bench: GitHub + Cloudflare Pages hosting"

# ── Stage 1: preflight ────────────────────────────────────────────────────
stage "Preflight"
say "Checking the tools this wizard leans on. Nothing is changed in this stage."
say "Project root: $ROOT"
say "Parent repo:  $PARENT"
[[ -d "$ROOT/.git" ]] || { warn "$ROOT is not a git repo. Run: git init -b main && git add -A && git commit"; exit 1; }
[[ "$(git rev-parse --abbrev-ref HEAD)" == "main" ]] || warn "You are on branch '$(git rev-parse --abbrev-ref HEAD)', not main. Stages 5-7 push main."
git -C "$PARENT" rev-parse --show-toplevel >/dev/null 2>&1 || { warn "$PARENT is not a git repo; the submodule stage will fail."; }
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  say "${GREEN}✓${RESET} gh is installed and logged in ($(gh api user -q .login 2>/dev/null || echo '?'))"
else
  warn "gh is missing or logged out. Run: gh auth login"; exit 1
fi
say "Testing SSH alias '$SSH_HOST' (answer 'yes' if asked to trust github.com's host key)..."
ssh_out=$(ssh -o BatchMode=no -T "git@${SSH_HOST}" 2>&1 || true)
if grep -q "successfully authenticated" <<<"$ssh_out"; then
  say "${GREEN}✓${RESET} SSH alias works: $(grep -o 'Hi [^!]*' <<<"$ssh_out")"
else
  warn "ssh -T git@${SSH_HOST} did not authenticate:"; note "$ssh_out"
  confirm "Continue anyway?" || exit 1
fi
if [[ -n "$(git status --porcelain)" ]]; then
  note "Working tree has uncommitted changes (expected while another agent builds src/)."
  note "This wizard only ever commits the files it creates itself, by explicit path."
fi
say "Local build check (tsc + vite, should take a few seconds)..."
if npm run build >/dev/null 2>&1; then say "${GREEN}✓${RESET} npm run build passes"; else
  warn "npm run build fails locally; Cloudflare's build will fail the same way. Fix it first (another agent may be mid-edit)."
  confirm "Continue anyway?" || exit 1
fi
pause

# ── Stage 2: GitHub repository ────────────────────────────────────────────
stage "GitHub: create ${GH_OWNER}/${GH_REPO} and push main"
if gh repo view "${GH_OWNER}/${GH_REPO}" >/dev/null 2>&1; then
  vis=$(gh repo view "${GH_OWNER}/${GH_REPO}" --json visibility -q .visibility)
  say "${GREEN}✓${RESET} ${GH_OWNER}/${GH_REPO} already exists on GitHub ($vis). Skipping create."
else
  say "Visibility is your call. Cloudflare Pages works with either; a private repo keeps the"
  say "in-progress build and transcripts out of public view until you choose to open it."
  if confirm "Make the repo PRIVATE? (n = public)"; then VIS=private; else VIS=public; fi
  say "Running: gh repo create ${GH_OWNER}/${GH_REPO} --${VIS} --description \"...\""
  gh repo create "${GH_OWNER}/${GH_REPO}" "--${VIS}" \
    --description "The Watchmaker's Bench: learn why a mechanical watch runs fast or slow by regulating a simulated movement" \
    --disable-wiki
  say "${GREEN}✓${RESET} created (${VIS})"
fi
# gh would add an https remote; the parent repo and its sibling submodule push over the SSH alias instead.
if git remote get-url origin >/dev/null 2>&1; then
  if [[ "$(git remote get-url origin)" != "$SSH_URL" ]]; then
    say "Pointing origin at $SSH_URL"; git remote set-url origin "$SSH_URL"
  fi
else
  git remote add origin "$SSH_URL"
fi
say "${GREEN}✓${RESET} origin = $(git remote get-url origin)"
local_head=$(git rev-parse main)
remote_head=$(git ls-remote origin refs/heads/main 2>/dev/null | cut -f1 || true)
if [[ "$remote_head" == "$local_head" ]]; then
  say "${GREEN}✓${RESET} origin/main already at $local_head. Skipping push."
else
  say "Pushing main (${local_head:0:7}) to origin..."
  git push -u origin main
  remote_head=$(git ls-remote origin refs/heads/main | cut -f1)
  [[ "$remote_head" == "$local_head" ]] && say "${GREEN}✓${RESET} push verified: origin/main = ${remote_head:0:7}" \
                                          || { warn "origin/main ($remote_head) does not match local main ($local_head)"; exit 1; }
fi
write_env GH_REPO_URL "https://github.com/${GH_OWNER}/${GH_REPO}"
pause

# ── Stage 3: register as submodule in the parent repo ─────────────────────
stage "Parent repo: add ${SUBMODULE_PATH} as a submodule (commit, no push)"
say "The parent repo $PARENT tracks each website as a submodule; websites/shahparikh is the model."
note "Heads-up: the shahparikh entry in .gitmodules reads 'yourusername/shahparikh.git' (a placeholder);"
note "its checkout's real remote is ahparikh/shahparikh. This entry uses the real owner: $SSH_URL"
existing_url=$(git -C "$PARENT" config -f .gitmodules --get "submodule.${SUBMODULE_PATH}.url" 2>/dev/null || true)
if [[ -n "$existing_url" ]]; then
  say "${GREEN}✓${RESET} .gitmodules already has submodule.${SUBMODULE_PATH}.url = $existing_url"
  if [[ "$existing_url" != "$SSH_URL" ]]; then
    warn "That URL differs from $SSH_URL."
    if confirm "Rewrite it to $SSH_URL?"; then
      git -C "$PARENT" config -f .gitmodules "submodule.${SUBMODULE_PATH}.url" "$SSH_URL"
      git -C "$PARENT" submodule sync -- "$SUBMODULE_PATH" >/dev/null
    fi
  fi
else
  say "The folder already exists with its own .git and a pushed origin, so 'git submodule add' with"
  say "the URL and the existing path adopts it in place (no clone, no data moved):"
  note "  cd $PARENT"
  note "  git submodule add $SSH_URL $SUBMODULE_PATH"
  if confirm "Run that now?"; then
    ( cd "$PARENT" && git submodule add "$SSH_URL" "$SUBMODULE_PATH" )
    say "${GREEN}✓${RESET} .gitmodules now reads:"
    git -C "$PARENT" config -f .gitmodules --get-regexp "submodule.${SUBMODULE_PATH}\." | sed 's/^/    /'
  else
    SKIPPED+=("git submodule add $SSH_URL $SUBMODULE_PATH  (in $PARENT)")
  fi
fi
# Commit in the parent, only the two paths this step touches, and never push the parent.
if git -C "$PARENT" diff --cached --quiet -- .gitmodules "$SUBMODULE_PATH" \
   && git -C "$PARENT" diff --quiet -- .gitmodules "$SUBMODULE_PATH" \
   && git -C "$PARENT" ls-files --error-unmatch "$SUBMODULE_PATH" >/dev/null 2>&1; then
  say "${GREEN}✓${RESET} parent already has ${SUBMODULE_PATH} committed; nothing to commit."
else
  say "Parent changes to commit (only these two paths; shahparikh's dirty state is left alone):"
  git -C "$PARENT" status --short -- .gitmodules "$SUBMODULE_PATH" | sed 's/^/    /'
  if confirm "Commit in $PARENT? (this does NOT push)"; then
    git -C "$PARENT" add -- .gitmodules "$SUBMODULE_PATH"
    git -C "$PARENT" commit -q -m "Add watchmakers-bench (websites/anthropic) as submodule" \
      -m "Co-Authored-By: Claude Fable 5.1 <noreply@anthropic.com>" -- .gitmodules "$SUBMODULE_PATH"
    say "${GREEN}✓${RESET} committed: $(git -C "$PARENT" log --oneline -1)"
    note "Push the parent yourself when you are ready: git -C $PARENT push"
  else
    SKIPPED+=("commit .gitmodules + ${SUBMODULE_PATH} in $PARENT")
  fi
fi
pause

# ── Stage 4: Cloudflare Pages ─────────────────────────────────────────────
stage "Cloudflare Pages: connect the repo and run the first deploy"
if existing=$(_existing PAGES_URL) && [[ -n "$existing" ]] && _http_ok "$existing"; then
  say "${GREEN}✓${RESET} $existing already serves the site. Press Enter to keep it, or paste a new URL."
fi
say "Only you can authorise the GitHub app and log in to Cloudflare, so this part is in the browser."
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages/create/pages"
step "Log in if asked. You should land on Workers & Pages → Create → Pages."
step "Click 'Connect to Git' (if the deep link failed: Workers & Pages → Create → Pages tab)."
step "Pick GitHub. Authorise the 'Cloudflare Pages' GitHub app for the ${GH_OWNER} account;"
step "  under repository access choose 'Only select repositories' → ${GH_REPO}, then Install & Authorize."
step "Back in Cloudflare, select ${GH_OWNER}/${GH_REPO} and click 'Begin setup'."
say ""
say "Set up builds and deployments exactly like this:"
note "  Project name:         ${GH_REPO}    (becomes <project>.pages.dev; change it if taken)"
note "  Production branch:    main"
note "  Framework preset:     None   (or Vite; either way override the two fields below)"
note "  Build command:        npm run build"
note "  Build output dir:     dist"
note "  Root directory:       /      (NOT spike; leave the path field empty or '/')"
note "  Environment variables (Production AND Preview):"
note "      NODE_VERSION = 22"
note "  (Playwright's npm package does not download browsers on install; this was verified locally."
note "   Only if the build log shows a browser download, add PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD = 1.)"
step "Click 'Save and Deploy'. The first build runs tsc then vite; expect well under 2 minutes."
step "When it says Success, the page shows the production URL, like https://${GH_REPO}.pages.dev"
warn "If the build fails, open the log: a tsc error is intentional (type errors must fail the deploy);"
warn "a 'node: bad option' or 'Unsupported engine' means NODE_VERSION was not applied."
ask PAGES_URL "Paste the production URL (https://<project>.pages.dev):"
PAGES_URL="${PAGES_URL%/}"
until [[ "$PAGES_URL" =~ ^https://[a-z0-9-]+\.pages\.dev$ ]]; do
  warn "Expected something like https://${GH_REPO}.pages.dev (no path, no trailing slash)."
  ask PAGES_URL "Paste the production URL:"; PAGES_URL="${PAGES_URL%/}"
done
PAGES_PROJECT="${PAGES_URL#https://}"; PAGES_PROJECT="${PAGES_PROJECT%.pages.dev}"
say "Checking $PAGES_URL responds..."
if _wait_http "$PAGES_URL" 60; then say "${GREEN}✓${RESET} production URL is live"; else
  warn "No 2xx from $PAGES_URL yet. Continue once the dashboard shows Success."
  confirm "Continue anyway?" || exit 1
fi
write_env PAGES_URL "$PAGES_URL"
write_env PAGES_PROJECT "$PAGES_PROJECT"
pause

# ── Stage 5: verify production redeploys on push to main ──────────────────
stage "Verify: a docs-only push to main redeploys production"
PAGES_URL=$(_existing PAGES_URL); PAGES_PROJECT=$(_existing PAGES_PROJECT)
deploys_url="https://dash.cloudflare.com/?to=/:account/workers-and-pages/view/${PAGES_PROJECT}"
if [[ "$(_existing PROD_VERIFIED || true)" == "yes" ]]; then
  say "${GREEN}✓${RESET} already verified on a previous run. Skipping."
else
  stamp=$(date -u +%Y-%m-%dT%H:%M:%SZ)
  printf 'Deploy check %s: docs-only commit pushed to main by docs/hosting-wizard.sh\n' "$stamp" > docs/deploy-check.txt
  git add -- docs/deploy-check.txt
  git commit -q -m "docs: deploy check ${stamp}" -m "Co-Authored-By: Claude Fable 5.1 <noreply@anthropic.com>" -- docs/deploy-check.txt
  check_sha=$(git rev-parse HEAD)
  say "Committed ${check_sha:0:7} (only docs/deploy-check.txt). Pushing main..."
  git push origin main
  say "${GREEN}✓${RESET} pushed. Cloudflare should start a production build for ${check_sha:0:7} now."
  open_url "$deploys_url"
  step "On the project's Deployments tab, watch for a Production deployment of commit ${check_sha:0:7}."
  step "It should reach Success within 3 minutes, and $PAGES_URL keeps serving the site."
  say "Polling $PAGES_URL meanwhile (up to 3 min)"
  _wait_http "$PAGES_URL" 180 && say "${GREEN}✓${RESET} $PAGES_URL still answers 2xx" || warn "$PAGES_URL not answering"
  if confirm "Did the ${check_sha:0:7} production deployment succeed within 3 minutes?"; then
    write_env PROD_VERIFIED yes
  else
    warn "Open the failed build's log and fix the cause before continuing; re-run this wizard afterwards."
    exit 1
  fi
fi
pause

# ── Stage 6: verify a non-main branch gets a preview URL ──────────────────
stage "Verify: a throwaway branch gets a preview URL, then is deleted"
PAGES_URL=$(_existing PAGES_URL); PAGES_PROJECT=$(_existing PAGES_PROJECT)
preview_url="https://${PREVIEW_BRANCH}.${PAGES_PROJECT}.pages.dev"
if [[ "$(_existing PREVIEW_VERIFIED || true)" == "yes" ]]; then
  say "${GREEN}✓${RESET} already verified on a previous run. Skipping."
else
  say "The branch is created straight on the remote from a fresh commit object, so your working"
  say "tree and current branch are never touched (another agent may be editing src/)."
  if git ls-remote --exit-code --heads origin "$PREVIEW_BRANCH" >/dev/null 2>&1; then
    say "${GREEN}✓${RESET} origin/${PREVIEW_BRANCH} already exists; reusing it."
  else
    tree=$(git rev-parse 'HEAD^{tree}')
    c=$(git commit-tree "$tree" -p HEAD -m "chore: preview-URL check (throwaway branch)")
    git push origin "${c}:refs/heads/${PREVIEW_BRANCH}"
    say "${GREEN}✓${RESET} pushed ${c:0:7} as origin/${PREVIEW_BRANCH}"
  fi
  step "Expected preview URL: $preview_url"
  step "In the Deployments tab a 'Preview' deployment for ${PREVIEW_BRANCH} should appear and succeed."
  say "Polling the preview URL (up to 3 min)"
  if _wait_http "$preview_url" 180; then
    say "${GREEN}✓${RESET} preview is live at $preview_url"; open_url "$preview_url"
  else
    warn "No 2xx from $preview_url yet."; open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages/view/${PAGES_PROJECT}"
  fi
  if confirm "Did the preview deployment appear and production stay untouched?"; then
    write_env PREVIEW_VERIFIED yes
  else
    warn "Check Settings → Builds & deployments → Preview deployments is set to 'All non-Production branches'."
    confirm "Delete the throwaway branch anyway and continue?" || exit 1
  fi
  say "Deleting the throwaway branch..."
  git push origin --delete "$PREVIEW_BRANCH" && say "${GREEN}✓${RESET} remote branch deleted"
  git show-ref --verify --quiet "refs/heads/${PREVIEW_BRANCH}" && git branch -D "$PREVIEW_BRANCH" || true
  note "No local branch was created, so there is nothing to delete locally."
  note "Cloudflare keeps the old preview deployment listed; that is normal and harmless."
fi
pause

# ── Stage 7: record the URLs in the docs and push ─────────────────────────
stage "Record: write the URLs into docs/hosting.md, CLAUDE.md and README.md"
PAGES_URL=$(_existing PAGES_URL); PAGES_PROJECT=$(_existing PAGES_PROJECT)
preview_pattern="https://<branch>.${PAGES_PROJECT}.pages.dev"
export PAGES_URL preview_pattern
changed=()

# docs/hosting.md: a two-line block right under the H1 (skip if the URL is already there).
if ! grep -qF "$PAGES_URL" docs/hosting.md; then
  perl -0pi -e 's{\A(# [^\n]*\n)}{$1\n- **Production:** $ENV{PAGES_URL} (deploys from `main`)\n- **Previews:** $ENV{preview_pattern} (every other branch)\n}' docs/hosting.md
  changed+=(docs/hosting.md)
fi
# CLAUDE.md Status: replace the hosting bullet if it still says "not yet", else add after "## Status".
if ! grep -qF "$PAGES_URL" CLAUDE.md; then
  if grep -q 'Production URL: not yet' CLAUDE.md; then
    perl -pi -e 's{^- \*\*Hosting:\*\*.*Production URL: not yet\..*$}{- **Hosting:** Cloudflare Pages from GitHub `ahparikh/watchmakers-bench`; production $ENV{PAGES_URL} (push to `main`). Spec: `docs/hosting.md`.\n- **Previews:** $ENV{preview_pattern} for every non-`main` branch.}' CLAUDE.md
  else
    perl -0pi -e 's{(## Status\n\n)}{$1- **Hosting:** Cloudflare Pages; production $ENV{PAGES_URL} (push to `main`). Spec: `docs/hosting.md`.\n- **Previews:** $ENV{preview_pattern} for every non-`main` branch.\n}' CLAUDE.md
  fi
  changed+=(CLAUDE.md)
fi
# README.md: fill the placeholder.
if ! grep -qF "$PAGES_URL" README.md; then
  perl -pi -e 's{^Production URL: not yet deployed$}{Production URL: $ENV{PAGES_URL}\nPreview URLs: $ENV{preview_pattern}}' README.md
  changed+=(README.md)
fi
if (( ${#changed[@]} )); then
  say "Updated: ${changed[*]}"
  git --no-pager diff --stat -- "${changed[@]}" | sed 's/^/    /'
  git add -- "${changed[@]}"
  git commit -q -m "docs: record Cloudflare Pages production and preview URLs" \
    -m "Co-Authored-By: Claude Fable 5.1 <noreply@anthropic.com>" -- "${changed[@]}"
  git push origin main
  say "${GREEN}✓${RESET} committed and pushed $(git rev-parse --short HEAD)"
else
  say "${GREEN}✓${RESET} all three files already carry $PAGES_URL. Nothing to do."
fi
say ""
say "Production: $PAGES_URL"
say "Previews:   $preview_pattern"
note "Remember: the parent repo $PARENT has an unpushed submodule commit. Push it when you choose."
pause

finish
}

run_wizard "$@"; exit
